PROMPT_BASIC = "import Mathlib\n\nnamespace TuringTask\n\nnoncomputable def colored (k m : Nat) : Nat :=\n  Finset.sum (Finset.Nat.antidiagonalTuple k m) (fun f : Fin k -> Nat =>\n    Finset.prod Finset.univ (fun i : Fin k => Fintype.card (Nat.Partition (f i))))\n\nnoncomputable def eulerPow (e m : Nat) : Int :=\n  Polynomial.coeff (Finset.prod (Finset.range m) (fun i : Nat =>\n    ((1 : Polynomial Int) - Polynomial.X ^ (i + 1)) ^ e)) m\n\ntheorem colored_sub_three_dvd (p a m : Nat) (hp : Nat.Prime p) (h : Dvd.dvd p (8 * m + 1)) :\n    Dvd.dvd p (colored (a * p - 3) m) := by\n  sorry\n\ntheorem colored_sub_three_pow_dvd (p k a m : Nat) (hp : Nat.Prime p)\n    (h : forall x : Nat, Not (x ^ 2 % p = (8 * m + 1) % p)) :\n    Dvd.dvd (p ^ k) (colored (a * p ^ k - 3) m) := by\n  sorry\n\ntheorem colored_sub_four_dvd (p a m : Nat) (hp : Nat.Prime p) (h3 : p % 3 = 2)\n    (h : Dvd.dvd p (6 * m + 1)) :\n    Dvd.dvd p (colored (a * p - 4) m) := by\n  sorry\n\ntheorem colored_sub_six_sq_dvd (p a m : Nat) (hp : Nat.Prime p) (h4 : p % 4 = 3)\n    (h : Dvd.dvd p (4 * m + 1)) :\n    Dvd.dvd (p ^ 2) (colored (a * p ^ 2 - 6) m) := by\n  sorry\n\ntheorem eulerPow_odd_iff (s m : Nat) :\n    Odd (eulerPow (3 * 2 ^ s) m) <-> exists j : Nat, m = 2 ^ s * (j * (j + 1) / 2) := by\n  sorry\n\nend TuringTask\n"

def check():
    basic = FILES["TuringTask/Basic.lean"]
    # 1. every non-sorry line of the prompt skeleton appears in the golden, in order
    pos = 0
    for line in PROMPT_BASIC.splitlines():
        if line.strip() in ("", "sorry"):
            continue
        i = basic.find(line + "\n", pos)
        assert i >= 0, "prompt line missing or out of order: " + line
        pos = i + len(line)
    # 2. no forbidden constructs in any Lean source of the project
    for name, text in FILES.items():
        if name.endswith(".lean") and name != "StatementAndAxiomsCheck.lean":
            for bad in ("sorry", "admit", "native_decide", "axiom ", "unsafe ", "implemented_by", "extern"):
                assert bad not in text, name + " contains " + bad
    # 3. submission-field texts are pure ASCII
    for name, text in TEXTS.items():
        for ch in text:
            assert ch == "\n" or 32 <= ord(ch) <= 126, name + " has a non-ASCII character"
    assert TEXTS["task4_golden_explanation.txt"].count("$") % 2 == 0
    assert TEXTS["task4_golden_explanation_short.txt"].count("$") % 2 == 0
    crit = [l for l in TEXTS["task4_rubric.txt"].split("\n") if l.strip()]
    assert 5 <= len(crit) <= 20, "rubric must have 5 to 20 criteria"
    return crit

def main():
    out = sys.argv[1] if len(sys.argv) > 1 else os.path.dirname(os.path.abspath(__file__))
    crit = check()
    root = os.path.join(out, PROJECT)
    for name, text in FILES.items():
        path = os.path.join(root, *name.split("/"))
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, "w", encoding="utf-8", newline="\n") as f:
            f.write(text)
    for name, text in TEXTS.items():
        with open(os.path.join(out, name), "w", encoding="ascii", newline="\n") as f:
            f.write(text)
    zpath = os.path.join(out, PROJECT + ".zip")
    with zipfile.ZipFile(zpath, "w", zipfile.ZIP_DEFLATED) as z:
        for name in sorted(FILES):
            info = zipfile.ZipInfo(PROJECT + "/" + name, date_time=(2026, 10, 7, 0, 0, 0))
            info.compress_type = zipfile.ZIP_DEFLATED
            info.external_attr = 0o644 << 16
            z.writestr(info, FILES[name].encode("utf-8"))
    print("project folder :", root)
    print("zip to upload  :", zpath, hashlib.sha256(open(zpath, "rb").read()).hexdigest()[:16])
    for name in TEXTS:
        print("text file      :", os.path.join(out, name), len(TEXTS[name]), "chars")
    print("rubric criteria:", len(crit))
    print("lean sources   :", ", ".join(n for n in sorted(FILES) if n.endswith(".lean")))
    print("all checks passed")

if __name__ == "__main__":
    main()
